<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';
saas_require_login();$orgId=saas_require_organization();$tourId=saas_require_tour();saas_require_permission('tour.edit');$db=saas_db();$tour=saas_current_tour();
$error='';$saved=false;
$defaults=[
 'organization'=>['x'=>28,'y'=>20,'w'=>300,'h'=>28,'label'=>'Organization','demo'=>'GoZyraa Travels','size'=>15,'weight'=>700],
 'tour'=>['x'=>28,'y'=>52,'w'=>430,'h'=>42,'label'=>'Tour Name','demo'=>'Sylhet Weekend Escape','size'=>27,'weight'=>800],
 'dates'=>['x'=>28,'y'=>100,'w'=>330,'h'=>25,'label'=>'Dates','demo'=>'25–27 Sep 2026','size'=>13,'weight'=>600],
 'guest'=>['x'=>28,'y'=>145,'w'=>420,'h'=>34,'label'=>'Passenger Name','demo'=>'Gabriel Rozario','size'=>22,'weight'=>700],
 'phone'=>['x'=>28,'y'=>184,'w'=>260,'h'=>24,'label'=>'Phone','demo'=>'01712 345678','size'=>12,'weight'=>500],
 'bus'=>['x'=>28,'y'=>218,'w'=>210,'h'=>38,'label'=>'Bus','demo'=>'Hanif Coach','size'=>14,'weight'=>700],
 'bus_number'=>['x'=>246,'y'=>218,'w'=>145,'h'=>38,'label'=>'Bus No.','demo'=>'Dhaka Metro-Ga 12-3456','size'=>14,'weight'=>700],
 'seat'=>['x'=>28,'y'=>263,'w'=>145,'h'=>38,'label'=>'Seat','demo'=>'A-12','size'=>14,'weight'=>700],
 'room'=>['x'=>181,'y'=>263,'w'=>210,'h'=>38,'label'=>'Room','demo'=>'Room 204','size'=>14,'weight'=>700],
 'paid'=>['x'=>28,'y'=>307,'w'=>145,'h'=>32,'label'=>'Paid','demo'=>'৳ 4,500','size'=>12,'weight'=>700],
 'due'=>['x'=>181,'y'=>307,'w'=>170,'h'=>32,'label'=>'Due','demo'=>'৳ 1,500','size'=>12,'weight'=>700],
 'ticket'=>['x'=>28,'y'=>343,'w'=>240,'h'=>22,'label'=>'Ticket No.','demo'=>'GTM-2026-00125','size'=>10,'weight'=>700],
 'qr'=>['x'=>525,'y'=>100,'w'=>165,'h'=>165,'label'=>'QR Code','demo'=>'GTM-QR-00125','size'=>10,'weight'=>700],
];
$q=$db->prepare('SELECT * FROM tour_ticket_designs WHERE tour_id=? AND organization_id=? LIMIT 1');$q->execute([$tourId,$orgId]);$design=$q->fetch();
$elements=$design?json_decode((string)$design['elements_json'],true):$defaults;if(!is_array($elements))$elements=$defaults;
$background=(string)($design['background_image']??'');$name=(string)($design['design_name']??'Default');
function design_upload(string $field,int $tourId): string{
 if(empty($_FILES[$field])||($_FILES[$field]['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE)return '';
 $f=$_FILES[$field];if((int)$f['error']!==UPLOAD_ERR_OK)throw new RuntimeException('Could not upload the design image.');
 if((int)$f['size']>10*1024*1024)throw new RuntimeException('Design image must be 10 MB or smaller.');
 $info=@getimagesize((string)$f['tmp_name']);if(!$info)throw new RuntimeException('Invalid design image.');
 $mime=(string)($info['mime']??'');$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($allowed[$mime]))throw new RuntimeException('Design must be JPG, PNG or WebP.');
 $dir=__DIR__.'/uploads/tours/'.$tourId.'/ticket-design';if(!is_dir($dir)&&!@mkdir($dir,0775,true)&&!is_dir($dir))throw new RuntimeException('Could not create ticket design directory.');
 if(!is_writable($dir))throw new RuntimeException('Ticket design directory is not writable.');
 $file='background-'.bin2hex(random_bytes(8)).'.'.$allowed[$mime];if(!move_uploaded_file((string)$f['tmp_name'],$dir.'/'.$file))throw new RuntimeException('Could not save the design image.');
 return '/uploads/tours/'.$tourId.'/ticket-design/'.$file;
}
if($_SERVER['REQUEST_METHOD']==='POST'){try{
 saas_check_csrf();$posted=json_decode((string)($_POST['elements_json']??''),true);if(!is_array($posted))throw new RuntimeException('Invalid design layout.');
 foreach($posted as $k=>$v){
  if(!isset($defaults[$k])||!is_array($v)){unset($posted[$k]);continue;}
  foreach(['x','y','w','h','size','weight'] as $n)$posted[$k][$n]=max(1,min($n==='x'?719:($n==='y'?349:($n==='w'?720:($n==='h'?350:1200))),(int)($posted[$k][$n]??$defaults[$k][$n])));
  $posted[$k]['x']=min($posted[$k]['x'],max(0,720-$posted[$k]['w']));$posted[$k]['y']=min($posted[$k]['y'],max(0,350-$posted[$k]['h']));
 }
 $elements=$posted;$newBg=design_upload('background',$tourId);if($newBg!=='')$background=$newBg;$name=trim((string)($_POST['design_name']??'Default'))?:'Default';$q=$db->prepare('INSERT INTO tour_ticket_designs(tour_id,organization_id,design_name,canvas_width,canvas_height,background_image,elements_json,created_by) VALUES(?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE design_name=VALUES(design_name),background_image=VALUES(background_image),elements_json=VALUES(elements_json),updated_at=NOW()');$q->execute([$tourId,$orgId,$name,720,350,$background?:null,json_encode($elements,JSON_UNESCAPED_UNICODE),saas_user_id()]);$saved=true;}catch(Throwable $e){$error=$e->getMessage();}}
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ticket Designer — GoTM</title><style>
*{box-sizing:border-box}body{margin:0;background:#f3f6fa;color:#172033;font-family:Inter,Arial,sans-serif}.top{padding:16px 22px;background:#fff;border-bottom:1px solid #e5e7eb;display:flex;align-items:center;justify-content:space-between;gap:15px;position:sticky;top:0;z-index:20}.top h1{margin:0;font-size:20px}.muted{color:#667085;font-size:12px}.actions{display:flex;gap:8px;flex-wrap:wrap}.btn{border:1px solid #d0d5dd;background:#fff;color:#172033;padding:9px 13px;border-radius:9px;font-weight:800;text-decoration:none;cursor:pointer}.primary{background:#155eef;color:#fff;border-color:#155eef}.layout{display:grid;grid-template-columns:300px 1fr;min-height:calc(100vh - 70px)}.panel{background:#fff;border-right:1px solid #e5e7eb;padding:16px;overflow:auto}.panel h3{font-size:13px;margin:0 0 9px}.panel hr{border:0;border-top:1px solid #e5e7eb;margin:16px 0}.field{margin-bottom:10px}.field label{display:block;font-size:11px;font-weight:800;margin-bottom:5px}.field input{width:100%;padding:9px;border:1px solid #d0d5dd;border-radius:8px}.section-title{display:flex;align-items:center;justify-content:space-between;gap:8px;margin:14px 0 8px}.section-title h3{margin:0}.count{font-size:10px;color:#667085}.library,.active-list{display:grid;gap:6px}.element{padding:9px 10px;border:1px solid #e4e7ec;border-radius:9px;background:#f8fafc;cursor:grab;font-weight:800;font-size:11px;display:flex;align-items:center;justify-content:space-between;gap:8px}.element:hover{border-color:#98a2b3;background:#f2f4f7}.element.dragging{opacity:.45}.element .add{border:0;background:#e7efff;color:#155eef;border-radius:7px;font-weight:900;padding:4px 7px;cursor:pointer}.active-row{display:flex;align-items:center;gap:6px}.active-row .name{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.remove{border:0;background:#fff0f0;color:#b42318;border-radius:7px;padding:4px 7px;cursor:pointer;font-weight:900}.selected-controls{margin-top:10px;padding:10px;border:1px solid #dbe4f0;border-radius:10px;background:#f8fafc}.selected-controls strong{font-size:11px}.control-grid{display:grid;grid-template-columns:1fr 1fr;gap:7px;margin-top:8px}.control-grid label{font-size:9px;font-weight:800;color:#667085}.control-grid input{width:100%;padding:6px;border:1px solid #d0d5dd;border-radius:6px;background:#fff}.hint{font-size:10px;line-height:1.45;color:#667085}.demo-note{font-size:10px;line-height:1.45;color:#475467;background:#eef4ff;padding:9px;border-radius:8px;margin-top:9px}.stage-wrap{overflow:auto;padding:35px}.stage{width:720px;height:350px;position:relative;background:#fff center/100% 100% no-repeat;box-shadow:0 15px 45px #10182820;margin:auto}.stage:after{content:'';position:absolute;inset:0;border:1px dashed #94a3b8;pointer-events:none}.drop-active{outline:3px solid #84adff;outline-offset:3px}.item{position:absolute;border:1px dashed #155eef88;background:#ffffffcf;cursor:move;padding:4px 7px;overflow:visible;white-space:nowrap;user-select:none}.item.selected{outline:2px solid #155eef}.item.qr{background:#fff;padding:0;display:flex;align-items:center;justify-content:center}.item.qr svg{width:100%;height:100%;display:block}.resize-handle{position:absolute;width:11px;height:11px;right:-6px;bottom:-6px;background:#155eef;border:2px solid #fff;border-radius:3px;cursor:nwse-resize;z-index:5}.qr-demo-text{position:absolute;bottom:2px;left:0;right:0;text-align:center;font-size:7px;font-weight:800;background:#ffffffd9;padding:1px}.help{font-size:10px;line-height:1.5;color:#667085;background:#f8fafc;padding:10px;border-radius:9px;margin-top:12px}.alert{padding:10px;margin:12px 20px;border-radius:9px}.ok{background:#ecfdf3;color:#067647}.err{background:#fef3f2;color:#b42318}@media(max-width:900px){.layout{grid-template-columns:1fr}.panel{border-right:0;border-bottom:1px solid #e5e7eb}.stage-wrap{padding:15px}}
</style></head><body>
<header class="top"><div><h1>Ticket Visual Designer</h1><div class="muted"><?=saas_h($tour['name'])?> · Canvas 720 × 350 px · A4 portrait · 3 tickets per sheet</div></div><div class="actions"><a class="btn" href="tickets.php">Back to Tickets</a><button class="btn primary" id="saveBtn" type="button">Save Design</button></div></header>
<?php if($saved):?><div class="alert ok">Design saved. All tickets now use these positions dynamically.</div><?php endif;?><?php if($error):?><div class="alert err"><?=saas_h($error)?></div><?php endif;?>
<form id="designForm" method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=saas_h(saas_csrf())?>"><input type="hidden" name="elements_json" id="elementsJson"><div class="layout"><aside class="panel">
<h3>Design settings</h3><div class="field"><label>Design name</label><input name="design_name" value="<?=saas_h($name)?>"></div><div class="field"><label>Background / ticket artwork</label><input type="file" name="background" accept="image/jpeg,image/png,image/webp"></div><div class="muted">Recommended artwork: 720 × 350 px. A4 portrait, 3 tickets per sheet with cutting gap. JPG/PNG/WebP, max 10 MB.</div>
<div class="section-title"><h3>Available fields</h3><span class="count" id="availableCount"></span></div><div class="library" id="library"></div>
<div class="section-title"><h3>On canvas</h3><span class="count" id="activeCount"></span></div><div class="active-list" id="elements"></div>
<div class="selected-controls" id="controls"><strong id="selectedTitle">Select a field</strong><div class="control-grid"><label>Width<input id="width<script>
const defs=<?=json_encode($defaults,JSON_UNESCAPED_UNICODE)?>;let state=<?=json_encode($elements,JSON_UNESCAPED_UNICODE)?>;const stage=document.getElementById('stage'),library=document.getElementById('library'),list=document.getElementById('elements');let selected=null;
const labels=Object.fromEntries(Object.entries(defs).map(([k,v])=>[k,v.label]));
function clamp(n,min,max){return Math.max(min,Math.min(max,n));}
function demoSvg(key){let seed=0;for(const ch of key)seed=(seed*31+ch.charCodeAt(0))%997;let cells='';const size=21;for(let y=0;y<size;y++)for(let x=0;x<size;x++){const finder=(x<7&&y<7)||(x>13&&y<7)||(x<7&&y>13);let on=finder?((x===0||x===6||y===0||y===6||(x>=2&&x<=4&&y>=2&&y<=4))):((seed+x*17+y*29+x*y*7)%5<2);if(on)cells+=`<rect x="${x}" y="${y}" width="1" height="1"/>`;}return `<svg viewBox="0 0 21 21" preserveAspectRatio="none" aria-hidden="true"><rect width="21" height="21" fill="#fff"/>${cells}</svg>`;}
function select(k){if(!state[k])return;selected=k;render();}
function addField(k,x=35,y=35){if(state[k]){select(k);return;}const d=defs[k];state[k]={...d,x:clamp(x,0,720-d.w),y:clamp(y,0,350-d.h)};select(k);}
function removeField(k){if(!state[k])return;delete state[k];if(selected===k)selected=null;render();}
function updateSize(axis,value){if(!selected||!state[selected])return;const v=state[selected];const min=10;if(selected==='qr'){const s=clamp(Number(value)||165,min,350);v.w=s;v.h=s;}else if(axis==='w'){v.w=clamp(Number(value)||v.w,min,720);v.x=clamp(v.x,0,720-v.w);}else{v.h=clamp(Number(value)||v.h,min,350);v.y=clamp(v.y,0,350-v.h);}render();}
function render(){
 stage.querySelectorAll('.item').forEach(e=>e.remove());library.innerHTML='';list.innerHTML='';
 Object.entries(defs).forEach(([key,d])=>{if(state[key])return;const row=document.createElement('div');row.className='element';row.draggable=true;row.dataset.key=key;row.innerHTML=`<span>${d.label}</span><button class="add" type="button">＋</button>`;row.querySelector('.add').onclick=()=>addField(key);row.addEventListener('dragstart',e=>{e.dataTransfer.setData('text/plain',key);e.dataTransfer.effectAllowed='copy';row.classList.add('dragging')});row.addEventListener('dragend',()=>row.classList.remove('dragging'));library.appendChild(row);});
 Object.keys(state).forEach(key=>{const row=document.createElement('div');row.className='element active-row';row.innerHTML=`<span class="name">${labels[key]}</span><button class="remove" type="button" title="Remove field">×</button>`;row.onclick=()=>select(key);row.querySelector('.remove').onclick=e=>{e.stopPropagation();removeField(key)};list.appendChild(row);});
 Object.entries(state).forEach(([key,v])=>{const el=document.createElement('div');el.className='item'+(key==='qr'?' qr':'');el.dataset.key=key;el.style.left=v.x+'px';el.style.top=v.y+'px';el.style.width=v.w+'px';el.style.height=v.h+'px';el.style.fontSize=v.size+'px';el.style.fontWeight=v.weight;if(key==='qr'){el.innerHTML=demoSvg(key)+`<span class="qr-demo-text">${defs[key].demo}</span>`;}else{el.textContent=defs[key].demo;}if(key===selected)el.classList.add('selected');stage.appendChild(el);el.addEventListener('mousedown',e=>{if(e.target.classList.contains('resize-handle'))return;drag(e,key)});const handle=document.createElement('span');handle.className='resize-handle';handle.title='Resize';handle.addEventListener('mousedown',e=>resizeStart(e,key));el.appendChild(handle);});
 document.getElementById('availableCount').textContent=Object.keys(defs).filter(k=>!state[k]).length+' available';document.getElementById('activeCount').textContent=Object.keys(state).length+' on canvas';
 const title=document.getElementById('selectedTitle'),wi=document.getElementById('widthInput'),hi=document.getElementById('heightInput');if(selected&&state[selected]){title.textContent=labels[selected];wi.value=state[selected].w;hi.value=state[selected].h;wi.disabled=false;hi.disabled=false;document.getElementById('controlHint').textContent=selected==='qr'?'QR Code stays square. Drag the blue corner to make it larger or smaller.':'Drag to move; use the blue corner to resize.';}else{title.textContent='Select a field';wi.value='';hi.value='';wi.disabled=true;hi.disabled=true;document.getElementById('controlHint').textContent='Drag a field to move it. Use the blue corner handle to resize it.';}
}
function drag(e,key){e.preventDefault();select(key);const startX=e.clientX,startY=e.clientY,ox=state[key].x,oy=state[key].y;function move(ev){state[key].x=clamp(Math.round(ox+ev.clientX-startX),0,720-state[key].w);state[key].y=clamp(Math.round(oy+ev.clientY-startY),0,350-state[key].h);render();}function up(){document.removeEventListener('mousemove',move);document.removeEventListener('mouseup',up);}document.addEventListener('mousemove',move);document.addEventListener('mouseup',up);}
function resizeStart(e,key){e.preventDefault();e.stopPropagation();select(key);const startX=e.clientX,startY=e.clientY,ow=state[key].w,oh=state[key].h,ox=state[key].x,oy=state[key].y;function move(ev){let w=clamp(Math.round(ow+ev.clientX-startX),10,720-ox),h=clamp(Math.round(oh+ev.clientY-startY),10,350-oy);if(key==='qr'){const s=clamp(Math.max(w,h),10,Math.min(720-ox,350-oy));w=s;h=s;}state[key].w=w;state[key].h=h;render();}function up(){document.removeEventListener('mousemove',move);document.removeEventListener('mouseup',up);}document.addEventListener('mousemove',move);document.addEventListener('mouseup',up);}
stage.addEventListener('dragover',e=>{e.preventDefault();stage.classList.add('drop-active');});stage.addEventListener('dragleave',()=>stage.classList.remove('drop-active'));stage.addEventListener('drop',e=>{e.preventDefault();stage.classList.remove('drop-active');const key=e.dataTransfer.getData('text/plain');if(!defs[key])return;const r=stage.getBoundingClientRect();addField(key,Math.round((e.clientX-r.left)-defs[key].w/2),Math.round((e.clientY-r.top)-defs[key].h/2));});
document.getElementById('widthInput').addEventListener('change',e=>updateSize('w',e.target.value));document.getElementById('heightInput').addEventListener('change',e=>updateSize('h',e.target.value));
document.getElementById('saveBtn').onclick=()=>{document.getElementById('elementsJson').value=JSON.stringify(state);document.getElementById('designForm').submit()};render();
</script>